  const q=d.quests[f.get('questId')],o=q?.objectives.find(x=>x.id===f.get('objectiveId'));if(!q||!o)throw new Error('Choose a quest and objective.');const amount=clampNum(f.get('amount'),1,9999),delta=Math.min(amount,o.target-o.progress);if(delta<=0)throw new Error('This objective is already complete.');mutate(x=>{const xx=x.quests[q.id].objectives.find(z=>z.id===o.id);xx.progress+=delta;const id=activity(x,{date:at,kind:'quest',label:`${q.title} — ${o.text}: +${delta} (${xx.progress}/${xx.target})`,refId:q.id});x.activities[id].delta=delta;x.activities[id].objectiveId=o.id;});state.modal=null;notify('Quest progress recorded.');return;
