  const category=f.get('category'),count=clampNum(f.get('count'),1,99999),name=String(f.get('name')||'').trim();if(name&&count!==1)throw new Error('Record a named discovery as a single item. Use an unnamed count for multiple finds.');const free=CATEGORIES[category]-collectionTotals(d).counts[category];if(count>free)throw new Error(`Only ${free} unrecorded ${CATEGORY_NAMES[category]} entries remain.`);mutate(x=>{countDiscoveries(x,category,count,{date:at,name,baseline:type==='baseline'});if(category==='crops'&&name&&!Object.values(x.crops).some(c=>c.name.toLowerCase()===name.toLowerCase())){const id=uid();x.crops[id]={id,name,seasons:[],grow:null,regrow:0,notes:'Growth information not yet recorded.'};}});state.modal=null;notify(type==='baseline'?'Starting collection progress added.':'Discovery recorded in the Daily Chronicle.');return;
